export const ACTIVE_LISTENING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Dengar vs menyimak",q:"Apa beda 'mendengar' & 'mendengarkan (menyimak)'?",options:["Mendengar hanya menangkap suara; mendengarkan berarti sengaja memusatkan perhatian untuk memahami maksud pembicara","Keduanya artinya sama persis, hanya berbeda cara menulis & mengucapkannya saja dalam kalimat sehari-hari","Mendengarkan berarti sengaja menutup telinga supaya suara-suara lain dari luar tidak terdengar sama sekali oleh kita"],answer:0,explain:"Telinga bisa menangkap suara tanpa kamu benar-benar paham. Menyimak butuh niat & perhatian.",hint:"Yang mana butuh usaha & perhatian?"},
{n:2,type:"mcq",micro:"Tujuan menyimak",q:"Tujuan utama mendengarkan aktif adalah...",options:["Menunggu giliran bicara supaya pendapatmu bisa segera didengar oleh semua orang","Benar-benar memahami apa yang dimaksud & dirasakan orang lain","Membuktikan bahwa kamu lebih pintar daripada orang yang sedang berbicara padamu"],answer:1,explain:"Mendengarkan aktif berfokus pada memahami orang lain, bukan menyiapkan bantahan.",hint:"Memahami orang lain, atau memenangkan pembicaraan?"},
{n:3,type:"mcq",micro:"Kontak mata",q:"Saat temanmu bercerita, menatapnya sesekali (kontak mata yang wajar) menunjukkan...",options:["Kamu menantang dia","Kamu sedang bosan","Kamu memberi perhatian & menganggap ceritanya penting"],answer:2,explain:"Kontak mata yang wajar (bukan menatap tajam terus-menerus) adalah tanda kamu hadir & peduli.",hint:"Melihat orang yang bicara, atau melihat ke mana-mana?"},
{n:4,type:"mcq",micro:"Menghentikan kegiatan lain",q:"Cara paling sederhana menunjukkan kamu siap menyimak:",options:["Meletakkan HP/kegiatan lain sejenak & menghadap ke pembicara","Berjalan menjauh","Tetap main HP sambil sesekali menjawab 'iya'"],answer:0,explain:"Perhatian terbagi membuat kamu melewatkan hal penting & pembicara merasa tidak dihargai.",hint:"Bisakah kamu benar-benar menyimak sambil menonton video?"},
{n:5,type:"mcq",micro:"Tidak memotong",q:"Ketika seseorang belum selesai bicara, sebaiknya kamu...",options:["Langsung memotong dengan pendapatmu sendiri begitu kamu merasa tahu arah ceritanya","Menunggu ia menyelesaikan kalimatnya sebelum menanggapi","Melengkapi semua kalimatnya supaya ia tidak perlu berlama-lama menjelaskan sendiri"],answer:1,explain:"Memotong membuat pembicara kehilangan alur & merasa tidak didengar. Beri ruang sampai selesai.",hint:"Sebelum atau sesudah ia selesai?"},
{n:6,type:"mcq",micro:"Anggukan & 'hmm'",q:"Menganggukkan kepala atau berkata 'oh', 'lalu?' saat menyimak berfungsi untuk...",options:["Mengganggu konsentrasi pembicara sehingga ia lupa apa yang ingin disampaikan tadi","Menyuruh pembicara cepat-cepat selesai karena kamu sudah ingin pergi dari situ","Menunjukkan kamu mengikuti & mendorong ia melanjutkan"],answer:2,explain:"Tanda-tanda kecil ini disebut 'pintu pembuka' — memberi tahu pembicara bahwa kamu menyimak.",hint:"Mendorong ia bercerita, atau menghentikannya?"},
{n:7,type:"mcq",micro:"Mengulang inti",q:"Setelah teman bercerita, kamu berkata 'Jadi tadi kamu kesal karena dijanjikan tapi tidak ditepati, ya?' Ini disebut...",options:["Memantulkan/merangkum — memastikan kamu menangkap maksudnya dengan benar","Menghakimi","Menyela"],answer:0,explain:"Merangkum ulang dengan kata-katamu sendiri membuktikan kamu menyimak & memberi kesempatan pembicara meluruskan.",hint:"Kamu mengecek pemahamanmu, atau menilai dia?"},
{n:8,type:"mcq",micro:"Menyimak perasaan",q:"Mendengarkan aktif bukan hanya menangkap fakta, tetapi juga...",options:["Merek baju yang dipakai pembicara serta harga barang-barang yang ia bawa hari itu","Perasaan di balik cerita (senang, kecewa, takut)","Nilai ujian pembicara dibandingkan dengan nilai ujianmu sendiri minggu lalu di sekolah"],answer:1,explain:"Sering yang paling ingin didengar orang adalah perasaannya, bukan sekadar urutan kejadian.",hint:"Apa lagi selain 'apa yang terjadi'?"},
{n:9,type:"order",micro:"Langkah menyimak sederhana",q:"Urutkan langkah mendengarkan teman yang sedang bercerita.",items:["Berhenti sejenak dari kegiatan lain & menghadap ke teman","Diam & menyimak sampai ia selesai, sambil mengangguk sesekali","Ulangi inti ceritanya dengan kata-katamu untuk memastikan paham","Tanggapi perasaannya, baru beri pendapat bila diminta"],answer:[0,1,2,3],explain:"Siap → simak penuh → cek pemahaman → tanggapi. Pendapat/nasihat datang paling akhir.",hint:"Apa yang dilakukan sebelum kamu boleh menanggapi?"},
{n:10,type:"mcq",micro:"Gangguan menyimak",q:"Contoh hal yang membuat kamu gagal menyimak dengan baik:",options:["Menghadap pembicara, diam sejenak, dan menatapnya dengan perhatian yang tenang","Bertanya untuk memperjelas bagian cerita yang belum kamu pahami dengan sopan","Memikirkan jawaban sambil orang masih bicara, melihat HP, atau buru-buru menilai"],answer:2,explain:"Perhatian yang bocor ke pikiran sendiri atau layar membuat kamu melewatkan maksud sebenarnya.",hint:"Mana yang memecah perhatianmu?"},
{n:11,type:"tf",micro:"Diam itu bagian menyimak",q:"Benar atau Salah: Memberi jeda diam sejenak setelah orang selesai bicara — sebelum kamu menanggapi — adalah bagian dari mendengarkan yang baik.",answer:true,explain:"Jeda singkat menunjukkan kamu memikirkan ucapannya, bukan sekadar menunggu giliran. Ia juga memberi ruang bila pembicara ingin menambah.",hint:"Langsung menyahut, atau beri jeda kecil dulu?"},
{n:12,type:"tf",micro:"Menyimak = setuju?",q:"Benar atau Salah: Mendengarkan seseorang dengan sungguh-sungguh berarti kamu pasti setuju dengan semua yang ia katakan.",answer:false,explain:"Sebaliknya, kamu bisa menyimak dengan penuh perhatian & tetap punya pendapat berbeda. Menyimak adalah memahami, bukan menyetujui.",hint:"Paham dengan maksud orang sama artinya dengan sependapat?"},
{n:13,type:"mcq",micro:"Bahasa tubuh menyimak",q:"Postur tubuh yang menunjukkan kamu menyimak:",options:["Menghadap pembicara, badan sedikit condong ke depan, wajah tenang","Menutup mata & menunduk ke meja","Membelakangi pembicara & menyilangkan tangan erat sambil menghela napas"],answer:0,explain:"Tubuh yang terbuka & sedikit condong berkata 'aku tertarik & hadir'.",hint:"Terbuka & menghadap, atau tertutup & membelakangi?"},
{n:14,type:"mcq",micro:"Menyimak instruksi",q:"Saat guru memberi instruksi tugas, mendengarkan aktif berarti...",options:["Menebak-nebak sendiri isi tugasnya lalu langsung mengerjakan tanpa bertanya kepada siapa pun","Menyimak sampai selesai, mencatat poin penting, & bertanya bila ada yang belum jelas","Mengobrol dengan teman sebelahnya & menyalin catatan mereka nanti setelah jam pelajaran selesai"],answer:1,explain:"Menyimak instruksi dengan baik menghemat waktu & menghindari kesalahan mengerjakan.",hint:"Simak + catat + tanya, atau tebak sendiri?"},
{n:15,type:"mcq",micro:"'Mendengarkan untuk membalas'",q:"Kebiasaan 'mendengarkan hanya untuk menyiapkan balasan' membuat kamu...",options:["Menjadi pendengar terbaik di kelas karena kamu selalu siap dengan jawaban yang tepat","Lebih paham perasaan orang lain karena kamu terus memikirkan balasanmu sendiri sejak awal","Melewatkan sebagian isi karena pikiranmu sibuk menyusun kata-kata sendiri"],answer:2,explain:"Kalau otakmu sibuk merancang jawaban, ia tidak sedang memproses ucapan orang.",hint:"Fokusmu pada ucapan dia, atau pada jawabanmu nanti?"},
{n:16,type:"mcq",micro:"Menyimak orang yang berbeda",q:"Mendengarkan aktif juga berlaku saat berbicara dengan orang yang pendapatnya berbeda darimu, karena...",options:["Kamu bisa memahami alasan mereka & menanggapi dengan tepat, bukan menyerang tebakan","Kamu harus langsung membantah setiap kalimat mereka supaya pendapatmu yang menang akhirnya","Pendapat yang berbeda dari pendapatmu sama sekali tidak perlu didengarkan oleh siapa pun"],answer:0,explain:"Memahami dulu posisi lawan bicara membuat tanggapanmu lebih tepat sasaran & percakapan lebih sehat.",hint:"Paham dulu alasan mereka, atau langsung membantah?"},
{n:17,type:"mcq",micro:"Nada 'aku dengar kamu'",q:"Kalimat yang menunjukkan kamu benar-benar menyimak curhat teman:",options:["'Ah, itu sih masalah kecil saja. Punyaku jauh lebih parah daripada punyamu tadi.'","'Kedengarannya berat ya. Ceritakan lebih lanjut kalau kamu mau.'","'Sudahlah, jangan dipikirkan lagi. Nanti juga hilang sendiri tanpa kamu repot-repot.'"],answer:1,explain:"Mengakui perasaan & membuka ruang bercerita lebih menenangkan daripada membandingkan atau menutup pembicaraan.",hint:"Mana yang mengakui perasaan temanmu?"},
{n:18,type:"mcq",micro:"Menyimak di telepon",q:"Saat menyimak lewat telepon (tanpa melihat wajah), tanda menyimak yang penting adalah...",options:["Menyalakan TV keras-keras supaya suasana terasa ramai & lawan bicara tahu kamu ada","Diam total tanpa suara sama sekali karena kamu yakin lawan bicara pasti tahu kamu menyimak","Sesekali bersuara ('iya', 'oh begitu') & merangkum, karena lawan bicara tidak bisa melihat anggukanmu"],answer:2,explain:"Tanpa isyarat visual, suara kecil & rangkuman menjadi satu-satunya cara pembicara tahu kamu masih menyimak.",hint:"Lawan bicara bisa melihat anggukanmu lewat telepon?"},
{n:19,type:"mcq",micro:"Menyimak nama & detail",q:"Saat berkenalan, mendengarkan aktif membantu kamu...",options:["Mengingat nama & detail penting sehingga percakapan berikutnya terasa lebih hangat","Segera melupakan nama orang itu begitu perkenalan selesai supaya otakmu tidak penuh","Tidak perlu peduli siapa mereka sebenarnya karena kamu hanya butuh berkenalan sebentar saja"],answer:0,explain:"Mengingat nama & hal kecil ('katanya kamu suka menggambar') menunjukkan kamu benar-benar hadir saat itu.",hint:"Apa efek mengingat nama seseorang?"},
{n:20,type:"open",micro:"Merancang kebiasaan menyimak",q:"Kamu sadar sering memotong pembicaraan orang & memikirkan HP saat teman bercerita. Tulis 3 kebiasaan konkret yang akan kamu latih untuk menjadi pendengar yang lebih baik, beserta alasan tiap kebiasaan.",explain:"Jawaban baik menyebut 3 kebiasaan nyata (mis. singkirkan HP, tahan diri sampai orang selesai, rangkum ulang inti/perasaan sebelum menanggapi) dengan alasan yang menghubungkan tiap kebiasaan ke perhatian penuh dan rasa dihargai.",hint:"Pikirkan: apa yang kamu lakukan dengan HP, kapan kamu boleh bicara, dan bagaimana memastikan kamu paham.",sample:"(1) Meletakkan HP menghadap ke bawah atau memasukkannya ke saku saat seseorang mulai bercerita — supaya perhatianku tidak terbelah dan teman merasa dihargai. (2) Menunggu sampai orang benar-benar selesai bicara (menghitung satu-dua dalam hati) sebelum aku menanggapi — supaya aku tidak memotong dan sempat memahami maksud utuhnya. (3) Sebelum memberi pendapat, mengulang inti cerita dengan kata-kataku sendiri, misalnya 'jadi kamu kesal karena...' — supaya aku yakin sudah menangkap maksud dan perasaannya dengan benar, dan teman tahu aku menyimak."},
{n:21,type:"classify",micro:"Menyimak vs tidak menyimak",q:"Kelompokkan tiap perilaku ke 'Mendengarkan aktif' atau 'Bukan mendengarkan aktif'.",items:["Menghadap pembicara & menaruh HP","Merangkum ulang: 'Jadi maksudmu...'","Memotong untuk menceritakan pengalamanmu sendiri","Melihat jam berkali-kali sambil menjawab singkat"],groups:["Mendengarkan aktif","Bukan mendengarkan aktif"],answer:{"Mendengarkan aktif":["Menghadap pembicara & menaruh HP","Merangkum ulang: 'Jadi maksudmu...'"],"Bukan mendengarkan aktif":["Memotong untuk menceritakan pengalamanmu sendiri","Melihat jam berkali-kali sambil menjawab singkat"]},explain:"Menyimak aktif: perhatian penuh + mengecek pemahaman. Bukan menyimak: memotong, mengalihkan ke diri sendiri, atau menunjukkan ingin cepat selesai.",hint:"Mana yang membuat pembicara merasa didengar?"},
{n:22,type:"mcq",micro:"Parafrase",q:"'Parafrase' dalam menyimak berarti...",options:["Menirukan persis kata-kata pembicara tanpa mengubah satu huruf pun seperti burung beo","Menyampaikan kembali inti ucapan dengan kata-katamu sendiri untuk memastikan paham","Mengubah maksud pembicara menjadi sesuatu yang lain supaya cerita terdengar lebih menarik"],answer:1,explain:"Parafrase yang baik menangkap inti + perasaan, memakai bahasamu sendiri, dan diakhiri nada bertanya ('...begitu?').",hint:"Kata-katamu sendiri, atau meniru persis?"},
{n:23,type:"mcq",micro:"Pertanyaan klarifikasi",q:"Kalau ada bagian cerita yang membingungkan, cara menyimak yang baik adalah...",options:["Menebak sendiri bagian yang membingungkan itu lalu menanggapi berdasarkan tebakanmu saja","Diam saja & pura-pura mengerti supaya pembicara tidak merasa harus mengulang penjelasannya","Bertanya sopan untuk memperjelas: 'Boleh diulang bagian yang tadi?'"],answer:2,explain:"Bertanya untuk memperjelas menunjukkan kamu serius menyimak & mencegah salah paham.",hint:"Menebak diam-diam, atau bertanya terus terang?"},
{n:24,type:"mcq",micro:"Menyimak empatik",q:"'Menyimak dengan empati' berarti...",options:["Mencoba merasakan situasi dari sudut pandang pembicara, bukan hanya menilai dari sudut pandangmu","Selalu menangis bersama orang lain setiap kali ia bercerita hal sedih kepadamu di sekolah","Memberi solusi secepat mungkin tanpa perlu mendengar perasaan pembicara sampai selesai bercerita"],answer:0,explain:"Empati saat menyimak: 'Kalau aku di posisinya, mungkin aku juga merasa begitu.' Ini membuat orang merasa dimengerti.",hint:"Dari sudut pandang siapa kamu mencoba memahami?"},
{n:25,type:"mcq",micro:"Hambatan: menghakimi cepat",q:"Menghakimi pembicara dalam hati ('ah, dia lebay') sejak awal cerita membuat kamu...",options:["Menyimak lebih jernih karena kamu sudah punya kesimpulan tentang orang itu sejak awal cerita","Menyaring sisa cerita lewat penilaian itu & melewatkan maksud sebenarnya","Menjadi pendengar netral yang adil karena penilaianmu sejak awal selalu tepat tentang orangnya"],answer:1,explain:"Sekali kamu melabeli pembicara, otakmu cenderung hanya menangkap hal yang mendukung label itu.",hint:"Apa yang terjadi setelah kamu buru-buru menilai?"},
{n:26,type:"mcq",micro:"Hambatan: memberi nasihat terlalu cepat",q:"Saat teman baru mulai curhat & kamu langsung memberi daftar solusi, sering kali ia merasa...",options:["Bangga padamu","Sangat terbantu & lega","Tidak benar-benar didengar, karena ia mungkin hanya ingin didengarkan dulu"],answer:2,explain:"Tanyakan dulu: 'Kamu mau didengar saja, atau mau masukan?' Banyak orang butuh yang pertama lebih dulu.",hint:"Solusi cepat selalu yang dibutuhkan orang yang curhat?"},
{n:27,type:"tf",micro:"Menyimak butuh energi",q:"Benar atau Salah: Mendengarkan aktif membutuhkan usaha & fokus, jadi wajar bila terasa melelahkan setelah percakapan yang panjang & serius.",answer:true,explain:"Menyimak sungguh-sungguh adalah kerja mental. Mengenali ini membantumu memilih waktu yang tepat untuk percakapan penting.",hint:"Menyimak penuh itu santai total atau butuh tenaga?"},
{n:28,type:"tf",micro:"Multitasking saat menyimak",q:"Benar atau Salah: Kebanyakan orang bisa menyimak percakapan penting dengan baik sambil mengerjakan hal lain yang butuh pikiran, seperti membalas pesan.",answer:false,explain:"Sebaliknya, otak tidak benar-benar memperhatikan dua hal sekaligus; ia berpindah cepat & kehilangan potongan informasi. Untuk percakapan penting, hentikan kegiatan lain.",hint:"Bisakah kamu benar-benar fokus pada dua hal sekaligus?"},
{n:29,type:"mcq",micro:"Menyimak sampai tuntas",q:"'Mendengarkan sampai tuntas sebelum menyimpulkan' penting karena...",options:["Bagian akhir cerita sering mengubah arti keseluruhan","Kesimpulan awal yang muncul di kepalamu selalu benar sehingga bagian akhir tidak terlalu perlu","Tidak ada gunanya menunggu cerita selesai karena bagian akhir tidak pernah mengubah arti ceritanya"],answer:0,explain:"Menyimpulkan di tengah cerita berisiko salah paham; kalimat terakhir bisa membalik semuanya.",hint:"Apakah akhir cerita bisa mengubah maknanya?"},
{n:30,type:"order",micro:"Menanggapi curhat dengan menyimak",q:"Urutkan cara menanggapi teman yang sedang kesal bercerita.",items:["Simak penuh tanpa memotong sampai ia selesai","Akui perasaannya: 'Wajar kamu kesal soal itu'","Tanya: 'Kamu mau aku dengarkan saja, atau mau masukan?'","Beri tanggapan sesuai jawabannya"],answer:[0,1,2,3],explain:"Simak → akui perasaan → tanyakan kebutuhannya → tanggapi sesuai. Jangan langsung ke solusi.",hint:"Kapan kamu boleh bertanya apa yang ia butuhkan?"},
{n:31,type:"mcq",micro:"Isyarat 'lanjutkan'",q:"Kalimat pendek seperti 'terus?', 'lalu?', 'oh ya?' saat menyimak disebut dorongan minimal & berguna untuk...",options:["Menekan pembicara agar diam","Menunjukkan kamu mengikuti & mengundang ia melanjutkan cerita","Mengubah topik"],answer:1,explain:"Dorongan minimal menjaga cerita tetap mengalir tanpa kamu mengambil alih pembicaraan.",hint:"Mengundang lanjut, atau menghentikan?"},
{n:32,type:"tf",micro:"Menyimak nama perasaan",q:"Benar atau Salah: Kamu sebaiknya tidak pernah menebak perasaan pembicara ('kelihatannya kamu kecewa'), karena bila tebakanmu meleset kamu pasti merusak percakapan.",answer:false,explain:"Sebaliknya, menyebut perasaan yang kamu tangkap membantu orang merasa dimengerti; kalau meleset, ia akan meluruskan ('bukan kecewa, lebih bingung') dan itu tetap kemajuan menuju saling paham.",hint:"Menebak perasaan lalu dikoreksi — membantu atau merusak?"},
{n:33,type:"mcq",micro:"Menyimak tanpa merebut cerita",q:"Teman cerita kakinya terkilir. Respons menyimak yang baik:",options:["'Oh dulu aku pernah patah tulang, lebih parah. Jadi gini...'","'Ya sudah, lain kali hati-hati.'","'Aduh, sakit ya? Gimana kejadiannya?'"],answer:2,explain:"Menahan diri untuk tidak langsung membajak cerita dengan pengalamanmu sendiri adalah inti menyimak.",hint:"Mana yang menjaga cerita tetap milik temanmu?"},
{n:34,type:"mcq",micro:"Menyimak bahasa non-verbal",q:"Saat menyimak, memperhatikan wajah & nada suara pembicara membantu kamu...",options:["Menangkap perasaan yang mungkin tidak diucapkan langsung","Menghakimi penampilannya dari ujung rambut sampai ujung kaki sebelum ia selesai bicara","Mengabaikan kata-katanya karena wajah & nada suara sudah cukup untuk menyimpulkan semuanya"],answer:0,explain:"Kadang mulut berkata 'aku baik-baik saja' tapi suara bergetar. Menyimak utuh berarti membaca keduanya.",hint:"Kata-kata saja, atau kata-kata + nada + wajah?"},
{n:35,type:"mcq",micro:"Menyimak dalam kelompok",q:"Dalam diskusi kelompok, mendengarkan aktif terlihat dari...",options:["Berbicara paling keras & paling sering supaya ide-idemu lebih dulu didengar oleh seluruh kelompok","Menyimak giliran orang lain & menanggapi apa yang baru mereka katakan, bukan hanya menunggu untuk membacakan idemu","Menyiapkan poinmu sendiri sambil mengabaikan yang lain sampai tiba giliranmu untuk berbicara nanti"],answer:1,explain:"Diskusi yang baik menyambung — tiap orang menanggapi ucapan sebelumnya, bukan bicara sendiri-sendiri.",hint:"Menyambung ucapan orang, atau menunggu giliran monolog?"},
{n:36,type:"mcq",micro:"Menyimak saat tidak setuju",q:"Kamu tidak setuju dengan pendapat teman. Cara menyimak yang baik sebelum membalas:",options:["Potong di tengah pembicaraannya & langsung menyebut bahwa pendapatnya salah sebelum ia selesai","Diam sambil memutar mata supaya ia tahu kamu tidak setuju tanpa perlu membalas apa pun","Ulangi dulu pendapatnya dengan adil sampai ia berkata 'ya, itu maksudku', baru sampaikan pandanganmu"],answer:2,explain:"Membuktikan kamu paham posisi lawan ('ujian steelman') membuat bantahanmu lebih dihargai & tepat sasaran.",hint:"Apa yang kamu lakukan sebelum membantah?"},
{n:37,type:"tf",micro:"Menyimak anak kecil / adik",q:"Benar atau Salah: Mendengarkan aktif hanya perlu dilakukan kepada orang dewasa; kepada anak kecil atau adik cukup mendengar sekilas saja.",answer:false,explain:"Sebaliknya, menyimak serius (mis. berjongkok setara mata) juga penting untuk anak & adik — anak yang merasa didengar belajar bahwa perasaannya penting & lebih mau bercerita di lain waktu.",hint:"Menyimak serius hanya untuk orang dewasa?"},
{n:38,type:"mcq",micro:"Menyimak & mengingat",q:"Setelah menyimak penjelasan panjang, cara memastikan kamu mengingatnya:",options:["Mengulang poin-poin utama dalam hati atau mencatatnya segera setelah selesai","Berharap otakmu menyimpan semuanya secara otomatis tanpa perlu mengulang atau mencatat apa pun","Langsung memikirkan hal lain yang lebih menyenangkan supaya pikiranmu tidak terasa terlalu lelah"],answer:0,explain:"Mengulang & mencatat segera memindahkan informasi dari ingatan sesaat ke ingatan yang lebih tahan lama.",hint:"Menyimpan otomatis, atau perlu diulang?"},
{n:39,type:"mcq",micro:"Menahan 'membetulkan'",q:"Teman salah menyebut nama pemain, tapi inti ceritanya soal kekecewaannya kalah bertanding. Pendengar aktif akan...",options:["Menertawakan kesalahannya menyebut nama pemain itu di depan teman-teman yang lain supaya seru","Fokus pada kekecewaannya dulu; koreksi kecil bisa nanti atau tidak perlu sama sekali","Langsung menyela untuk membetulkan nama itu dulu sebelum ia sempat melanjutkan ceritanya yang sedih"],answer:1,explain:"Menyela demi detail kecil yang tidak mengubah inti membuat pembicara merasa cerita & perasaannya tidak penting.",hint:"Yang penting nama pemainnya, atau perasaan temanmu?"},
{n:40,type:"open",micro:"Menganalisis percakapan gagal",q:"Rina bercerita ke Doni bahwa ia sedih nilainya turun. Doni langsung berkata, 'Makanya belajar. Aku aja bisa dapat bagus.' Rina jadi diam & pergi. Jelaskan minimal 3 kesalahan menyimak Doni, dan tuliskan satu tanggapan yang lebih baik.",explain:"Jawaban baik menyebut minimal 3 kesalahan (menghakimi, membajak cerita ke diri sendiri, melompat ke nasihat, tidak bertanya/tidak mengakui perasaan) dan memberi satu tanggapan alternatif yang mengakui perasaan + mengundang Rina melanjutkan.",hint:"Perhatikan: apa yang Doni lakukan pada perasaan Rina, pada siapa fokus pindah, dan seberapa cepat ia menasihati.",sample:"Kesalahan Doni: (1) Ia langsung menghakimi ('makanya belajar') alih-alih mengakui perasaan sedih Rina. (2) Ia mengalihkan pembicaraan ke dirinya sendiri ('aku aja bisa dapat bagus'), sehingga cerita berhenti jadi milik Rina. (3) Ia melompat ke nasihat/solusi padahal Rina belum selesai bercerita dan mungkin hanya ingin didengar. (4) Ia tidak bertanya apa pun untuk memahami situasi Rina. Tanggapan yang lebih baik: 'Wah, pasti kecewa ya nilainya turun padahal sudah berusaha. Mau cerita bagian mana yang paling bikin kamu kepikiran?' — ini mengakui perasaan, menjaga cerita tetap milik Rina, dan membuka ruang untuk melanjutkan."},
{n:41,type:"mcq",micro:"Skenario: teman gugup",q:"Sahabatmu akan tampil lomba & berkata gugup. Respons pendengar aktif:",options:["'Halah, gitu aja kok gugup. Santai saja, semua orang juga pernah lomba kok.'","'Aku sibuk sekali sekarang, nanti saja ya ceritanya kalau aku sudah tidak capek.'","'Gugup itu tandanya kamu peduli. Ceritakan, bagian mana yang paling bikin deg-degan?'"],answer:2,explain:"Mengakui perasaan + mengundang bercerita lebih membantu daripada meremehkan atau menutup pembicaraan.",hint:"Mana yang mengakui perasaan & membuka ruang cerita?"},
{n:42,type:"mcq",micro:"Skenario: instruksi bertingkat",q:"Guru menjelaskan tugas dengan 5 langkah cepat. Cara menyimak terbaik:",options:["Catat tiap langkah dengan singkat, lalu ulang kembali ke guru: 'Jadi langkahnya 1... 2... betul?'","Mengandalkan ingatan saja & langsung mulai bekerja karena lima langkah itu pasti mudah diingat","Bertanya pada teman setelah kelas bubar & mengerjakan sesuai ingatan mereka tentang langkah-langkahnya"],answer:0,explain:"Mencatat + mengonfirmasi ulang memastikan kamu tidak melewatkan langkah & menghemat waktu revisi.",hint:"Catat + konfirmasi, atau andalkan ingatan?"},
{n:43,type:"mcq",micro:"Skenario: orang tua lelah",q:"Ibu pulang kerja & bercerita harinya melelahkan. Kamu sedang asyik main game. Respons terbaik:",options:["Naikkan volume game","Jeda game sebentar, menghadap ibu, & menyimak; game bisa dilanjutkan setelah itu","'Iya iya' sambil terus menatap layar"],answer:1,explain:"Perhatian penuh selama beberapa menit jauh lebih berarti daripada 'iya-iya' setengah hati yang lama.",hint:"Beberapa menit perhatian penuh, atau lama tapi setengah hati?"},
{n:44,type:"mcq",micro:"Skenario: teman marah padamu",q:"Teman marah karena merasa kamu mengabaikannya. Langkah menyimak dulu:",options:["Langsung membela diri & menyebut bahwa ia terlalu berlebihan menanggapi hal yang kecil saja","Pergi meninggalkannya begitu saja supaya amarahnya reda sendiri tanpa kamu perlu mendengarkan apa pun","Dengarkan keluhannya sampai selesai & ulangi: 'Jadi kamu merasa diabaikan waktu aku...' sebelum menjelaskan sisimu"],answer:2,explain:"Saat orang marah, mereka perlu merasa didengar dulu sebelum bisa menerima penjelasanmu.",hint:"Dengar & akui dulu, atau bela diri dulu?"},
{n:45,type:"order",micro:"Latihan menyimak berpasangan",q:"Urutkan langkah latihan 'menyimak 2 menit' berpasangan.",items:["Satu orang bercerita bebas selama 2 menit, satu orang hanya menyimak","Pendengar tidak memotong, hanya mengangguk & memberi dorongan minimal","Setelah selesai, pendengar merangkum apa yang ia tangkap","Pembicara mengoreksi/menambahkan, lalu bertukar peran"],answer:[0,1,2,3],explain:"Bercerita → simak tanpa memotong → rangkum → koreksi & tukar peran. Latihan ini melatih menahan diri & memantulkan.",hint:"Apa yang pendengar lakukan setelah pembicara selesai?"},
{n:46,type:"mcq",micro:"Skenario: cerita membosankan",q:"Teman bercerita panjang tentang hal yang kurang kamu minati. Sikap sopan:",options:["Tetap beri perhatian wajar & dorongan minimal; kamu bisa mengarahkan topik dengan halus nanti","Terang-terangan menguap & melihat HP supaya ia tahu kamu bosan lalu cepat mengganti topiknya","Memotong dengan nada tinggi: 'Ini penting nggak sih? Aku nggak tertarik sama sekali.'"],answer:0,explain:"Menyimak juga soal menghormati. Kamu boleh membatasi waktu dengan sopan, bukan dengan meremehkan.",hint:"Bosan bukan alasan untuk bersikap kasar."},
{n:47,type:"mcq",micro:"Skenario: dua orang bicara sekaligus",q:"Dalam kelompok, dua teman bicara bersamaan. Pendengar aktif membantu dengan...",options:["Diam saja & membiarkan keadaan jadi kacau sampai keduanya berhenti berbicara dengan sendirinya","'Sebentar, satu-satu ya. Ana dulu, lalu Budi.'","Ikut berbicara keras-keras supaya suaramu yang menang & kedua temanmu akhirnya terdiam semua"],answer:1,explain:"Menjaga giliran bicara adalah bagian dari menyimak kelompok — memastikan semua benar-benar terdengar.",hint:"Menata giliran, atau ikut ramai?"},
{n:48,type:"mcq",micro:"Skenario: kabar sedih",q:"Teman mengabari hewan peliharaannya mati. Respons menyimak yang baik:",options:["'Kan cuma kucing saja, beli lagi aja yang baru, harganya juga tidak terlalu mahal kok.'","Langsung mengganti topik ke hal lucu supaya ia cepat melupakan kesedihannya dan tertawa lagi","'Aku turut sedih. Kamu pasti kehilangan banget. Aku di sini kalau kamu mau cerita.'"],answer:2,explain:"Mengakui kehilangan & menawarkan kehadiran lebih menghibur daripada mengecilkan perasaan atau menghindar.",hint:"Mana yang mengakui rasa kehilangannya?"},
{n:49,type:"mcq",micro:"Skenario: menyimak keluhan pelanggan (peran)",q:"Kamu berjualan & pembeli komplain barangnya salah. Menyimak aktif berarti...",options:["Dengarkan seluruh keluhan tanpa memotong, ulangi masalahnya, lalu tawarkan solusi","Langsung membela diri: 'Nggak mungkin salah, kami selalu memeriksa barang sebelum dikirim kok.'","Mengabaikan keluhan itu & menyuruh pembeli pergi saja karena sudah tidak mau berurusan lagi"],answer:0,explain:"Pelanggan yang merasa didengar jauh lebih mudah diajak menyelesaikan masalah dengan tenang.",hint:"Dengar & pahami keluhannya dulu, atau bantah dulu?"},
{n:50,type:"open",micro:"Menyusun tanggapan menyimak",q:"Adikmu berkata sambil hampir menangis: 'Aku nggak mau sekolah besok. Semua anak di kelas ngetawain aku waktu presentasi.' Tulis tanggapan yang menunjukkan mendengarkan aktif (bukan langsung menasihati atau meremehkan), lalu jelaskan mengapa tanggapanmu itu baik.",explain:"Jawaban baik memberi tanggapan yang: mengakui/menamai perasaan adik, tidak meremehkan, tidak langsung menasihati, dan mengundang dia melanjutkan cerita — lalu menjelaskan bahwa merasa didengar harus datang sebelum solusi.",hint:"Namai perasaannya, jangan meremehkan, jangan buru-buru menasihati, buka ruang cerita.",sample:"Tanggapan: 'Itu pasti bikin malu dan sakit hati banget ya, ditertawakan pas lagi di depan kelas. Wajar kalau kamu jadi nggak mau ke sekolah. Mau cerita ke aku gimana persisnya kejadiannya?' Mengapa baik: aku mengakui perasaan adik (malu, sakit hati) tanpa mengecilkannya, aku tidak langsung berkata 'ah biasa aja' atau 'makanya latihan dulu', dan aku mengundang dia bercerita lebih lanjut sehingga dia merasa didengar. Setelah dia merasa aman, baru nanti kami bisa bicara soal apa yang bisa dilakukan, dan aku bisa tanya apakah dia mau masukan atau ingin didengar saja."},
{n:51,type:"mcq",micro:"Menyimak & pertanyaan lanjutan",q:"Pertanyaan lanjutan yang menunjukkan kamu menyimak:",options:["'Kenapa sih kamu selalu saja punya masalah dengan orang lain setiap harinya seperti ini?'","'Tadi kamu bilang gurunya marah — marahnya seperti apa?' (menggali detail yang ia sebut)","'Ngomong-ngomong, kamu sudah nonton film baru yang lagi ramai dibicarakan itu belum?'"],answer:1,explain:"Pertanyaan lanjutan yang baik memakai kata-kata pembicara sendiri untuk menggali lebih dalam.",hint:"Mana yang menggali dari apa yang baru ia katakan?"},
{n:52,type:"tf",micro:"Menyimak lewat pesan teks",q:"Benar atau Salah: Mendengarkan aktif juga berlaku di percakapan teks — misalnya membaca pesan sampai selesai, menanggapi isinya, dan bertanya bila kurang jelas, bukan membalas asal cepat.",answer:true,explain:"Di teks, 'menyimak' berarti benar-benar membaca & menanggapi maksud orang, bukan sekadar mengetik balasan tercepat.",hint:"Membaca utuh & menanggapi maksud, atau membalas kilat tanpa membaca?"},
{n:53,type:"mcq",micro:"Menyimak saat lelah",q:"Kamu lelah tapi teman butuh cerita hal penting. Sikap jujur & sopan:",options:["Memaksakan menyimak sambil mengantuk berat & akhirnya melewatkan hampir setengah dari isi ceritanya","Berkata 'nanti aja' tanpa menyebut waktu yang jelas lalu menghilang & tidak pernah menanyakan lagi","'Aku mau dengar ini serius, tapi aku lagi capek banget. Boleh 20 menit lagi biar aku bisa fokus?'"],answer:2,explain:"Menunda dengan jujur & menyebut waktu pasti lebih menghormati daripada menyimak setengah sadar atau mengabaikan.",hint:"Menyimak buruk sekarang, atau menyimak baik sebentar lagi?"},
{n:54,type:"mcq",micro:"Skenario: menyimak orang yang gagap/pelan",q:"Lawan bicaramu berbicara lambat atau tersendat. Pendengar aktif...",options:["Sabar menunggu, tidak menyelesaikan kalimatnya, & menjaga kontak mata yang hangat","Menyelesaikan setiap kalimatnya sendiri supaya percakapan berjalan cepat & tidak membuang waktu","Menunjukkan wajah tidak sabar supaya ia sadar harus berbicara lebih cepat daripada tadi"],answer:0,explain:"Menyelesaikan kalimat orang lain terasa merendahkan. Beri waktu & ruang.",hint:"Sabar menunggu, atau menyerobot kalimatnya?"},
{n:55,type:"mcq",micro:"Menyimak kritik terhadap dirimu",q:"Seseorang menyampaikan bahwa perilakumu menyakitinya. Langkah menyimak:",options:["Langsung membalas dengan menyebutkan kesalahan-kesalahan mereka juga, supaya keadaan terasa impas & mereka berhenti menyalahkanmu","Tahan dorongan membela diri, dengarkan sampai selesai, ulangi inti keluhannya, lalu minta waktu memikirkannya bila perlu","Langsung menjelaskan panjang lebar bahwa mereka salah paham & tidak mengerti maksud baik di balik perilakumu yang sebenarnya"],answer:1,explain:"Menyimak kritik dengan tenang (bukan berarti langsung setuju) membuka jalan untuk memperbaiki hubungan.",hint:"Dengar penuh dulu, atau bela diri dulu?"},
{n:56,type:"mcq",micro:"Menyimak dalam wawancara/tanya guru",q:"Saat mewawancarai narasumber untuk tugas, mendengarkan aktif berarti...",options:["Membacakan semua pertanyaan dari daftar secara berurutan tanpa peduli apa jawaban yang diberikan oleh narasumber sebelumnya","Menyela tiap kali jawaban narasumber terasa panjang supaya wawancara cepat selesai & waktu belajar kelompok tidak terbuang","Menyimak jawaban & mengajukan pertanyaan susulan berdasarkan jawaban itu, bukan hanya membaca daftar pertanyaan berikutnya"],answer:2,explain:"Wawancara terbaik terasa seperti percakapan: pertanyaan berikutnya tumbuh dari jawaban sebelumnya.",hint:"Menanggapi jawaban, atau sekadar membaca daftar?"},
{n:57,type:"tf",micro:"Menyimak = tidak selalu menjawab",q:"Benar atau Salah: Tanggapan menyimak yang baik selalu harus berupa kata-kata; kalau kamu hanya diam berarti kamu tidak peduli.",answer:false,explain:"Sebaliknya, kadang tanggapan terbaik adalah diam yang penuh perhatian sambil menemani — saat orang sangat sedih, kehadiran yang tenang bisa lebih menghibur daripada rentetan nasihat.",hint:"Selalu harus ada jawaban, atau kadang cukup menemani?"},
{n:58,type:"mcq",micro:"Skenario: menyimak di rapat OSIS",q:"Dalam rapat, seorang anggota mengusulkan ide yang menurutmu kurang bagus. Menyimak aktif:",options:["Catat idenya, tanyakan alasannya, pastikan kamu paham, baru sampaikan kekhawatiranmu dengan menyebut bagian spesifik","Langsung berkata 'ide itu nggak akan jalan' di depan semua anggota supaya rapat cepat selesai","Mengabaikan usulan itu & langsung melanjutkan ke agenda berikutnya supaya waktu rapat tidak terbuang"],answer:0,explain:"Memahami alasan di balik ide membuat tanggapanmu lebih berbobot & si pengusul merasa dihargai.",hint:"Pahami alasannya dulu, atau tolak dulu?"},
{n:59,type:"mcq",micro:"Menyimak & menindaklanjuti",q:"Seminggu setelah teman cerita ia sakit, kamu bertanya 'Sudah enakan?'. Ini menunjukkan...",options:["Kamu sudah lupa isi cerita temanmu & hanya berbasa-basi saja supaya terlihat sopan di depannya","Kamu benar-benar menyimak & mengingat ceritanya, sehingga ia merasa diperhatikan","Kamu ikut campur urusan pribadi orang lain yang sebenarnya tidak perlu kamu ketahui sama sekali"],answer:1,explain:"Menindaklanjuti di kemudian hari adalah bukti kuat bahwa kamu menyimak, bukan sekadar mendengar lalu lupa.",hint:"Apa arti kamu masih ingat & menanyakannya lagi?"},
{n:60,type:"open",micro:"Rencana latihan sepekan",q:"Rancang latihan mendengarkan aktif untuk dirimu selama satu minggu: sebutkan minimal 4 tindakan konkret yang akan kamu coba (boleh di rumah, sekolah, atau chat) dan bagaimana kamu akan tahu apakah berhasil.",explain:"Jawaban baik memuat minimal 4 tindakan konkret (mis. singkirkan HP, tahan memotong, rangkum ulang, tanya kebutuhan sebelum menasihati, baca pesan utuh) DAN cara mengukur keberhasilan (mis. orang bercerita lebih banyak, lebih jarang menyela, lebih jarang salah paham).",hint:"Sebut tindakan yang bisa dihitung/diamati, lalu tanda nyata bahwa itu berhasil.",sample:"Latihan sepekan: (1) Setiap kali seseorang bercerita, aku menyingkirkan HP dan menghadap ke mereka — tanda berhasil: aku tidak lagi menengok layar di tengah cerita. (2) Aku menahan diri tidak memotong; kalau ada yang mau kukatakan, kutunggu sampai mereka berhenti. Tanda berhasil: berkurangnya momen aku menyela. (3) Sekali sehari, setelah orang bercerita, aku merangkum: 'Jadi maksudmu...'. Tanda berhasil: orang menjawab 'iya, betul' atau meluruskan, dan percakapan terasa lebih nyambung. (4) Saat teman curhat, aku bertanya dulu 'kamu mau didengar saja atau mau masukan?' sebelum memberi saran. Tanda berhasil: teman lebih banyak bercerita dan berkata merasa lega. (5) Di chat, aku membaca pesan panjang sampai habis sebelum membalas. Di akhir minggu aku menilai: apakah orang-orang bercerita lebih banyak kepadaku, dan apakah aku lebih jarang salah paham."},
{n:61,type:"mcq",micro:"Mengapa orang butuh didengar",q:"Mengapa merasa didengarkan begitu penting bagi orang?",options:["Karena mereka ingin menang dalam setiap argumen & membuat orang lain tidak bisa membantah","Tidak ada alasan khusus, itu hanya kebiasaan lama yang tidak berpengaruh apa-apa pada perasaan","Karena itu membuat mereka merasa dihargai, dipahami, & tidak sendirian menghadapi masalah"],answer:2,explain:"Kebutuhan untuk dipahami sangat mendasar; menyimak memenuhinya bahkan sebelum masalahnya selesai.",hint:"Apa yang dirasakan seseorang ketika benar-benar didengar?"},
{n:62,type:"mcq",micro:"Menyimak vs menunggu giliran",q:"Beda mendasar 'menyimak' & 'menunggu giliran bicara':",options:["Menyimak memproses & memahami ucapan orang; menunggu giliran hanya menahan diri sambil menyiapkan kata-kata sendiri","Keduanya sama","Menunggu giliran lebih sopan"],answer:0,explain:"Banyak percakapan sebenarnya adalah dua monolog bergantian. Menyimak sejati mengubahnya jadi dialog.",hint:"Memahami dia, atau menyusun jawabanmu?"},
{n:63,type:"tf",micro:"Menyimak membangun kepercayaan",q:"Benar atau Salah: Orang cenderung lebih memercayai & terbuka kepada seseorang yang terbukti mau mendengarkan mereka tanpa buru-buru menghakimi.",answer:true,explain:"Kepercayaan tumbuh dari pengalaman berulang 'aku bisa bercerita padanya & tidak dihakimi'.",hint:"Kamu lebih terbuka pada pendengar yang baik atau penghakim yang cepat?"},
{n:64,type:"mcq",micro:"Menilai kualitas menyimak",q:"Tanda seseorang BENAR-BENAR menyimakmu:",options:["Ia langsung mengalihkan pembicaraan ke ceritanya sendiri begitu kamu selesai mengucapkan satu kalimat","Ia menanggapi isi ucapanmu, mengingat detail nanti, & bertanya hal yang menyambung","Ia mengangguk terus-menerus tetapi tanggapannya sama sekali tidak nyambung dengan apa yang kamu katakan"],answer:1,explain:"Menyimak sejati terlihat dari tanggapan yang relevan & ingatan yang bertahan, bukan sekadar anggukan.",hint:"Anggukan kosong, atau tanggapan yang nyambung + ingat?"},
{n:65,type:"mcq",micro:"Mengapa memotong merugikan",q:"Memotong pembicaraan sering merugikan karena...",options:["Menghemat waktu sehingga percakapan selesai lebih cepat tanpa ada efek buruk apa pun pada pembicara","Membuat pembicara jadi lebih fokus & lebih bersemangat karena merasa ceritanya ditebak dengan benar","Pembicara kehilangan alur pikiran, merasa tidak dihargai, & kamu bisa salah menebak akhir yang belum ia ucapkan"],answer:2,explain:"Satu potongan bisa mematikan cerita & memicu rasa kesal yang bertahan lama.",hint:"Apa 3 kerugian sekaligus dari memotong?"},
{n:66,type:"tf",micro:"Empati vs setuju",q:"Benar atau Salah: Bila kamu berkata 'aku mengerti kenapa kamu merasa begitu', itu berarti kamu sudah menyetujui bahwa tindakan orang itu benar.",answer:false,explain:"Sebaliknya, memahami perasaan seseorang & menilai tindakannya adalah dua hal berbeda. Menyimak empatik tidak membutuhkan persetujuan.",hint:"Paham perasaan = membenarkan perbuatan?"},
{n:67,type:"mcq",micro:"Menyimak & salah paham",q:"Kebiasaan merangkum ulang ('jadi maksudmu...') mengurangi salah paham karena...",options:["Memberi pembicara kesempatan mengoreksi sebelum kamu bertindak berdasarkan tafsir yang keliru","Membuat percakapan jadi lebih lama saja tanpa ada manfaat apa pun bagi kedua belah pihak","Menunjukkan bahwa kamu tidak cukup pintar untuk memahami ucapan pembicara pada kali pertama saja"],answer:0,explain:"Salah paham paling mahal terjadi saat kamu yakin sudah mengerti padahal belum. Merangkum membongkarnya lebih awal.",hint:"Kapan lebih baik ketahuan salah tafsir: sekarang atau setelah bertindak?"},
{n:68,type:"mcq",micro:"Menyimak lintas budaya/usia",q:"Saat menyimak orang dari latar berbeda (usia, daerah, kebiasaan), sikap yang membantu:",options:["Berhenti menyimak begitu merasa orang itu terlalu berbeda, karena kamu yakin tidak akan pernah bisa memahami mereka sama sekali","Sadar bahwa cara mengungkapkan sesuatu bisa berbeda, jadi bertanya bila ragu daripada langsung menafsir dari kebiasaanmu sendiri","Menganggap semua orang pasti bermaksud persis sama seperti dirimu ketika mengucapkan kata-kata yang terdengar serupa di telingamu"],answer:1,explain:"Nada, jeda, & pilihan kata punya arti berbeda antar kelompok. Menyimak yang baik memberi ruang untuk itu.",hint:"Menafsir dari kebiasaanmu, atau memberi ruang untuk perbedaan?"},
{n:69,type:"mcq",micro:"Menyimak diri sendiri",q:"'Menyimak diri sendiri' (memperhatikan pikiran & perasaanmu saat percakapan) berguna karena...",options:["Membuatmu egois","Tidak ada hubungannya dengan menyimak orang lain","Kamu bisa menyadari saat mulai bosan, defensif, atau menghakimi — lalu memilih untuk kembali fokus"],answer:2,explain:"Pendengar yang baik menyadari 'gangguan dari dalam' & menariknya kembali ke pembicara.",hint:"Kalau kamu sadar sedang defensif, apa yang bisa kamu lakukan?"},
{n:70,type:"order",micro:"Dari salah paham ke pemahaman",q:"Urutkan proses meluruskan percakapan yang mulai salah paham.",items:["Sadari ada yang tidak nyambung (reaksi lawan bicara aneh)","Berhenti & akui: 'Sepertinya aku salah menangkap, boleh diulang?'","Simak ulang dengan perhatian penuh, tanpa asumsi lama","Rangkum ulang & minta konfirmasi sebelum lanjut"],answer:[0,1,2,3],explain:"Sadar → akui & minta ulang → simak tanpa asumsi → konfirmasi. Menahan ego untuk mengakui salah tangkap adalah kuncinya.",hint:"Apa langkah pertama sebelum bisa memperbaiki?"},
{n:71,type:"mcq",micro:"Menyimak & kepemimpinan",q:"Mengapa pemimpin tim yang baik biasanya pendengar yang baik?",options:["Dengan menyimak, ia menangkap masalah lebih awal, membuat anggota merasa dihargai, & mengambil keputusan berdasarkan informasi nyata","Karena pemimpin tidak perlu banyak bicara maupun mendengar, cukup menyuruh anggota tim melakukan semua pekerjaan sesuai kemauannya sendiri","Karena menyimak membuat pemimpin terlihat lemah di depan anggota, jadi ia lebih baik memberi perintah tanpa mendengar siapa pun"],answer:0,explain:"Tim yang merasa didengar lebih jujur melapor & lebih setia. Keputusan pun lebih tepat.",hint:"Apa yang didapat pemimpin dari mendengar anggotanya?"},
{n:72,type:"tf",micro:"Menyimak bisa dilatih",q:"Benar atau Salah: Mendengarkan aktif adalah keterampilan yang bisa dilatih & ditingkatkan, bukan bakat tetap yang dimiliki sejak lahir.",answer:true,explain:"Seperti keterampilan lain, menyimak membaik dengan kesadaran & latihan berulang — menahan memotong, merangkum, bertanya.",hint:"Bakat tetap, atau keterampilan yang bisa diasah?"},
{n:73,type:"mcq",micro:"Menyimak vs mengingat semua",q:"Mendengarkan aktif TIDAK berarti kamu harus mengingat setiap kata. Yang penting adalah...",options:["Menulis transkrip lengkap dari awal sampai akhir percakapan supaya tidak ada satu kata pun terlewat","Menangkap maksud utama & perasaan, serta membuat pembicara merasa dipahami saat itu","Merekam & menghafal seluruh kalimat pembicara kata demi kata supaya bisa mengulanginya dengan persis"],answer:1,explain:"Tujuannya pemahaman & koneksi, bukan hafalan sempurna. Catat detail penting bila perlu.",hint:"Hafal semua kata, atau tangkap maksud + perasaan?"},
{n:74,type:"mcq",micro:"Batas menyimak",q:"Menyimak yang sehat juga punya batas, misalnya...",options:["Kamu wajib mendengarkan apa pun yang dikatakan orang lain tanpa henti selamanya, walaupun sangat menyakitkan","Kamu tidak boleh punya perasaan sendiri selama menyimak karena yang penting hanya perasaan pembicara","Kamu boleh mengakhiri dengan sopan bila percakapan berubah menyakiti, menghina, atau kamu benar-benar tidak sanggup saat itu"],answer:2,explain:"Menyimak bukan berarti menjadi wadah tanpa batas. Menjaga diri tetap penting.",hint:"Menyimak tanpa batas, atau menyimak dengan batas yang sehat?"},
{n:75,type:"mcq",micro:"Menyimak & konflik",q:"Dalam pertengkaran, sering kali masalahnya bukan pokok soal, melainkan...",options:["Kedua pihak merasa tidak didengar, sehingga saling meninggikan suara untuk 'menang'","Salah satu pihak terlalu banyak menyimak sehingga lawannya jadi merasa menang & berhenti berbicara","Tidak ada hubungan sama sekali dengan menyimak, karena pertengkaran hanya soal siapa yang benar"],answer:0,explain:"Ketika satu pihak mulai benar-benar menyimak & mengakui perasaan pihak lain, ketegangan sering langsung turun.",hint:"Apa yang dirasakan orang yang berteriak dalam pertengkaran?"},
{n:76,type:"tf",micro:"Menyimak & media sosial",q:"Benar atau Salah: Di ruang digital, membalas cepat berdasarkan potongan kalimat sudah cukup; membaca komentar orang sampai selesai bukan bagian dari mendengarkan.",answer:false,explain:"Sebaliknya, membaca utuh & memahami maksud sebelum membalas adalah mendengarkan aktif versi digital. Banyak pertengkaran online terjadi karena orang membalas potongan kalimat tanpa membaca utuh.",hint:"Membalas potongan kalimat, atau memahami utuh dulu?"},
{n:77,type:"mcq",micro:"Menilai nasihat 'dengarkan saja'",q:"Nasihat 'kadang orang cuma butuh didengar, bukan dinasihati' berarti...",options:["Menyimak selalu lebih penting daripada bertindak dalam segala situasi, bahkan ketika ada bahaya nyata","Sebelum memberi solusi, cek apakah orang itu mencari solusi atau hanya ingin melepaskan beban & merasa ditemani","Kamu tidak boleh pernah memberi saran kepada siapa pun, apa pun alasan & keadaan yang sedang terjadi"],answer:1,explain:"Bertanya 'kamu mau masukan atau mau didengar saja?' mencegah kamu memberi nasihat yang tidak diminta.",hint:"Selalu diam, atau cek dulu apa yang dibutuhkan?"},
{n:78,type:"mcq",micro:"Menyimak & rasa ingin tahu",q:"Sikap batin yang paling menopang mendengarkan aktif:",options:["Rasa ingin menang","Rasa bosan yang ditutupi","Rasa ingin tahu yang tulus: 'Aku ingin benar-benar mengerti dunia dari sisi orang ini'"],answer:2,explain:"Ketika kamu benar-benar penasaran pada orang lain, menyimak menjadi mudah & wajar, bukan tugas.",hint:"Apa sikap batin yang membuat menyimak terasa alami?"},
{n:79,type:"mcq",micro:"Menyimak & tindak lanjut",q:"Setelah menyimak masalah teman, tindak lanjut yang menghormati:",options:["Melakukan apa yang kamu janjikan saat menyimak (mis. 'aku akan temani kamu bicara ke guru') & menanyakan kabarnya kemudian","Melupakan semua yang dibicarakan begitu percakapan selesai supaya kamu tidak terbebani oleh masalah orang lain yang berat-berat","Menceritakan masalah temanmu ke teman-teman lain supaya ada yang ikut membantu, tanpa perlu meminta izin dulu darinya sama sekali"],answer:0,explain:"Menyimak yang baik berlanjut menjadi tindakan yang bisa dipercaya & menjaga kerahasiaan.",hint:"Menepati janji + jaga rahasia, atau lupakan + sebarkan?"},
{n:80,type:"open",micro:"Membandingkan dua pendengar",q:"Bandingkan dua teman: Sinta selalu menjawab cepat, sering memotong, dan mengubah topik ke dirinya. Bayu diam, menatap, bertanya 'lalu?', dan minggu depan masih ingat ceritamu. Jelaskan siapa yang lebih membuat orang merasa didengar dan mengapa, lalu sebutkan 2 kebiasaan Bayu yang bisa kamu tiru.",explain:"Jawaban baik memilih Bayu, menjelaskan minimal 2-3 alasan (perhatian penuh, tidak membajak cerita, dorongan minimal, ingatan/tindak lanjut sebagai bukti menyimak) dan menyebut 2 kebiasaan Bayu yang konkret untuk ditiru.",hint:"Perhatikan: siapa yang menjaga cerita tetap milik pembicara, dan bukti apa bahwa seseorang benar-benar memproses ucapan.",sample:"Bayu jauh lebih membuat orang merasa didengar. Alasannya: ia memberi perhatian penuh (diam, menatap), ia tidak membajak pembicaraan ke dirinya sendiri sehingga cerita tetap milik lawan bicara, ia memakai dorongan minimal ('lalu?') yang membuat orang nyaman melanjutkan, dan ingatannya terhadap cerita minggu berikutnya membuktikan ia benar-benar memproses, bukan sekadar menunggu giliran. Sinta, meski responsif, membuat orang merasa cerita mereka tidak penting karena dipotong dan dialihkan. Dua kebiasaan Bayu yang bisa kutiru: (1) menahan diri tidak langsung menimpali dengan pengalamanku sendiri, dan (2) menindaklanjuti dengan menanyakan kabar cerita itu di kemudian hari."},
{n:81,type:"mcq",micro:"Kasus: menyimak dua pihak bertikai",q:"Dua temanmu bertengkar & masing-masing menceritakan versinya padamu. Peran pendengar yang membantu:",options:["Menceritakan versi satu pihak kepada pihak yang lain supaya mereka saling tahu isi hati masing-masing","Menyimak kedua versi dengan adil, memantulkan perasaan masing-masing, & tidak buru-buru memihak atau menyebarkan cerita","Langsung memutuskan siapa yang benar & siapa yang salah berdasarkan cerita yang kamu dengar pertama"],answer:1,explain:"Menyimak netral & menjaga cerita membuat kamu bisa membantu mereka bicara langsung, bukan memperkeruh.",hint:"Adil + jaga rahasia, atau langsung menghakimi + menyebar?"},
{n:82,type:"mcq",micro:"Kasus: menyimak saat kamu tersinggung",q:"Saat menyimak, lawan bicara mengatakan sesuatu yang menyinggungmu. Respons pendengar dewasa:",options:["Langsung membalas dengan kata-kata yang lebih menyakitkan supaya ia tahu rasanya disakiti seperti itu","Diam menahan marah tanpa berkata apa pun sampai akhirnya meledak di waktu yang tidak terduga nanti","Kenali reaksimu, beri jeda, & bila perlu katakan 'bagian tadi terasa menyakitkan buatku' sebelum melanjutkan menyimak"],answer:2,explain:"Menyadari & menyuarakan perasaanmu dengan tenang menjaga percakapan tetap jujur tanpa berubah jadi pertengkaran.",hint:"Kenali reaksi + suarakan dengan tenang, atau balas menyakiti / pendam?"},
{n:83,type:"tf",micro:"Refleksi: menyimak itu memberi",q:"Benar atau Salah: Memberi perhatian penuh saat mendengarkan seseorang adalah salah satu bentuk penghargaan paling sederhana namun bermakna yang bisa kamu berikan.",answer:true,explain:"Di dunia yang penuh gangguan, perhatian utuh adalah hadiah langka. Ia berkata: 'kamu penting, dan aku hadir untukmu.'",hint:"Perhatian penuh di zaman serba terdistraksi — biasa saja atau berharga?"},
{n:84,type:"mcq",micro:"Kasus: menyimak keluhan berulang",q:"Teman mengeluhkan masalah yang sama berkali-kali tanpa mengambil tindakan. Sikap menyimak yang sehat:",options:["Tetap mendengarkan dengan empati, tetapi boleh berkata jujur: 'Aku selalu siap dengar. Kamu mau kita pikirkan langkah kecil, atau kamu butuh dengar saja lagi?'","Memotong dengan berkata, 'Bosan aku dengar ini terus, kamu itu tidak pernah berubah sama sekali sejak dulu sampai sekarang, aku sudah capek!'","Menghindari temanmu itu selamanya supaya kamu tidak perlu lagi mendengar keluhan yang sama berulang-ulang setiap hari, walaupun ia sangat membutuhkanmu"],answer:0,explain:"Kamu bisa menjaga empati sambil menawarkan arah, tanpa menuduh atau meninggalkan.",hint:"Empati + tawaran arah yang jujur, atau meremehkan / kabur?"},
{n:85,type:"order",micro:"Menyimak lalu memfasilitasi",q:"Urutkan langkah membantu dua teman berdamai lewat menyimak.",items:["Dengarkan masing-masing sendiri, pantulkan perasaan & inti keluhannya","Ajak keduanya duduk bersama & sepakati aturan: bicara bergantian, tidak menghina","Minta tiap orang mengulang inti ucapan lawannya sebelum menjawab","Bantu mereka menemukan satu hal yang bisa disepakati untuk maju"],answer:[0,1,2,3],explain:"Simak terpisah → pertemukan dengan aturan → wajibkan saling memantulkan → cari titik temu. Menyimak adalah alat utamanya.",hint:"Sebelum dipertemukan, apa yang perlu dilakukan dengan tiap pihak?"},
{n:86,type:"mcq",micro:"Kasus: menyimak lewat bahasa isyarat/berbeda cara",q:"Teman barumu tuli & berkomunikasi dengan isyarat & tulisan. Mendengarkan aktif berarti...",options:["Menghindari percakapan dengannya karena berkomunikasi dengan isyarat & tulisan dianggap terlalu repot","Memberi perhatian penuh pada isyarat & tulisannya, tidak berpura-pura paham, & bersedia belajar cara komunikasinya","Berbicara lebih keras & lebih lambat sambil berharap ia bisa mendengar suaramu dengan lebih jelas"],answer:1,explain:"'Mendengarkan' pada intinya adalah memberi perhatian penuh untuk memahami — bentuknya menyesuaikan cara tiap orang berkomunikasi.",hint:"Inti menyimak adalah perhatian untuk memahami, apa pun salurannya."},
{n:87,type:"tf",micro:"Menyimak & privasi",q:"Benar atau Salah: Bagian dari menjadi pendengar yang bisa dipercaya adalah tidak menyebarkan cerita pribadi yang dibagikan seseorang kepadamu, kecuali ada bahaya serius yang perlu bantuan orang dewasa.",answer:true,explain:"Kepercayaan runtuh seketika bila cerita pribadi bocor. Pengecualiannya: bila seseorang dalam bahaya, melibatkan orang dewasa tepercaya adalah bentuk kepedulian.",hint:"Jaga rahasia — dengan satu pengecualian penting soal apa?"},
{n:88,type:"mcq",micro:"Kasus: menyimak orang yang sangat marah",q:"Seseorang berbicara padamu dengan sangat marah & suara tinggi (bukan kekerasan). Langkah menyimak yang menurunkan tensi:",options:["Ikut berteriak lebih keras daripada dia supaya suaramu terdengar jelas & ia tahu bahwa kamu sama sekali tidak takut","Berkata 'tenang dulu dong, jangan marah-marah' berulang-ulang supaya ia cepat berhenti & suasana kembali menjadi sepi","Tetap tenang, jaga nada rendah, biarkan ia menyelesaikan, lalu pantulkan: 'Kamu benar-benar marah soal ini. Aku dengar.'"],answer:2,explain:"Nada tenang & pengakuan perasaan sering meredakan; menyuruh 'tenang' malah menambah kesal.",hint:"Menandingi volume, atau tenang + mengakui perasaannya?"},
{n:89,type:"mcq",micro:"Kasus: menyimak vs perlu bertindak",q:"Teman bercerita ia dipukuli kakak kelas setiap hari & memintamu merahasiakannya. Sikap yang tepat:",options:["Dengarkan & tunjukkan kepedulian, tetapi jelaskan bahwa keselamatannya lebih penting daripada rahasia, & bantu ia melapor ke orang dewasa tepercaya","Merahasiakannya sepenuhnya karena ia memintamu begitu, & kamu tidak mau mengkhianati kepercayaannya dalam keadaan apa pun juga","Menyebarkan ceritanya ke semua teman di kelas supaya banyak orang tahu & mulai ikut mengejek kakak kelas yang memukulinya itu"],answer:0,explain:"Menyimak empatik tetap berlaku, tetapi ada batas: bahaya nyata membutuhkan bantuan orang dewasa, dan itu bentuk kesetiaan yang sebenarnya.",hint:"Rahasia mutlak, atau keselamatan lebih dulu dengan tetap peduli?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ketua kelompok proyek. Anggota bernama Tio jarang bicara di rapat; saat kamu tanya, ia hanya berkata 'terserah kalian aja'. Kamu curiga ia sebenarnya punya pendapat tapi merasa tak didengar. Rancang bagaimana kamu akan menggunakan mendengarkan aktif untuk membantunya ikut berkontribusi (minimal 4 langkah).",explain:"Jawaban baik memakai teknik menyimak konkret: bicara privat dulu, menyimak tanpa memotong + dorongan minimal, merangkum & konfirmasi ide, memberi ruang bicara di rapat sambil menjaga giliran, mengakui kontribusinya, dan menindaklanjuti — semuanya bertujuan membuat Tio merasa didengar sehingga mau berkontribusi.",hint:"Gabungkan: ruang aman (privat), menyimak penuh, merangkum, memberi panggung di rapat, mengapresiasi, menindaklanjuti.",sample:"(1) Bicara dengan Tio secara pribadi, bukan di depan kelompok, supaya ia lebih nyaman: 'Aku merasa kamu punya ide bagus tapi jarang sempat keluar di rapat. Aku mau dengar pendapatmu.' (2) Saat ia mulai bicara, aku benar-benar menyimak: tidak memotong, menatap, memberi dorongan minimal, dan tidak buru-buru menilai idenya. (3) Aku merangkum ulang idenya dengan kata-kataku dan mengonfirmasi: 'Jadi menurutmu bagian desain sebaiknya...begitu?' supaya ia tahu aku menangkapnya. (4) Di rapat berikutnya, aku sengaja memberi ruang: 'Tio, tadi kamu cerita ide soal desain, boleh kamu jelaskan ke teman-teman?' dan aku menjaga supaya tidak ada yang memotong. (5) Setelah idenya dipakai atau dibahas, aku menghargainya secara terbuka: 'ide Tio soal ini membantu.' (6) Aku menindaklanjuti dengan menanyakan pendapatnya lagi di kesempatan lain, supaya ia belajar bahwa di kelompok ini ia benar-benar didengar."},
{n:91,type:"mcq",micro:"Kasus: menyimak sambil mencatat",q:"Dalam rapat penting, kamu perlu mencatat sekaligus menyimak. Cara agar keduanya jalan:",options:["Tidak mencatat sama sekali & berharap semua isi rapat pasti akan bisa kamu ingat dengan baik nanti","Catat kata kunci singkat saja (bukan kalimat lengkap) & tetap angkat pandangan ke pembicara secara berkala","Menunduk menulis transkrip selengkap mungkin tanpa melihat siapa pun supaya tidak ada yang terlewat"],answer:1,explain:"Catatan kata kunci menjaga perhatianmu tetap sebagian besar pada pembicara, bukan pada kertas.",hint:"Kata kunci + sesekali angkat pandangan, atau transkrip penuh menunduk?"},
{n:92,type:"tf",micro:"Refleksi: menyimak mengubah percakapan",q:"Benar atau Salah: Percakapan yang tegang hanya bisa menjadi tenang bila kedua pihak berubah menyimak pada saat yang sama; satu orang saja tidak berpengaruh.",answer:false,explain:"Sebaliknya, menyimak menular: ketika satu pihak mulai benar-benar menyimak & merasa didengar, ia biasanya menurunkan pertahanan & mulai mendengarkan balik.",hint:"Butuh kedua pihak berubah sekaligus, atau satu langkah bisa memulai?"},
{n:93,type:"mcq",micro:"Kasus: menyimak orang yang pemalu bercerita",q:"Teman pemalu akhirnya mau bercerita hal pribadi dengan suara sangat pelan. Sikapmu:",options:["Menyuruhnya berbicara lebih keras berulang kali supaya kamu bisa mendengar ceritanya dengan jelas tanpa harus mendekat sedikit pun","Menganggap ceritanya tidak penting karena disampaikan dengan suara yang sangat pelan & hampir tidak terdengar oleh teman-teman lain","Dekatkan diri sedikit, beri perhatian tenang & sabar, jangan menyuruhnya 'yang keras dong', hargai keberaniannya bercerita"],answer:2,explain:"Menyimak yang baik menyesuaikan diri dengan pembicara & menghargai usaha yang dibutuhkannya untuk terbuka.",hint:"Menyesuaikan diri & menghargai keberaniannya, atau menuntut ia berubah?"},
{n:94,type:"mcq",micro:"Kasus: menyimak umpan balik guru",q:"Guru memberi banyak koreksi atas karyamu. Menyimak aktif berarti...",options:["Menahan rasa defensif, mencatat poin koreksi, bertanya bila tak jelas, & berterima kasih; menilai mana yang akan kamu terapkan setelah tenang","Membela diri atas setiap poin koreksi itu saat itu juga, supaya guru tahu alasan di balik setiap pilihan dalam karyamu","Mengangguk saja tanpa benar-benar mendengarkan, lalu mengabaikan seluruh koreksi itu begitu pelajaran usai & kamu pulang ke rumah"],answer:0,explain:"Umpan balik paling berguna bila kamu menyerap dulu, memilah setelah tenang, bukan menolak atau menelan mentah semuanya.",hint:"Serap + tanya + pilah nanti, atau bela diri / abaikan?"},
{n:95,type:"tf",micro:"Menyimak tidak berarti pasif",q:"Benar atau Salah: Mendengarkan aktif itu 'aktif' karena kamu melakukan banyak hal: fokus, membaca perasaan, merangkum, bertanya, menahan diri — bukan sekadar diam.",answer:true,explain:"Kata 'aktif' membedakannya dari sekadar 'ada di sana'. Pendengar aktif bekerja sepanjang percakapan.",hint:"Cuma diam, atau melakukan banyak hal dalam diam?"},
{n:96,type:"mcq",micro:"Kasus: menyimak di keluarga",q:"Ayah & kakak sering berdebat di rumah & keduanya tampak tidak saling dengar. Kontribusi kecilmu:",options:["Menyalahkan keduanya karena terlalu berisik & mengganggu seluruh anggota keluarga lain yang sedang beristirahat di rumah, lalu menyuruh mereka segera berhenti bicara","Saat berbicara terpisah dengan masing-masing, tunjukkan menyimak yang baik & pantulkan perasaan mereka, sehingga mereka punya contoh & merasa ada yang mendengar","Ikut berdebat & memihak salah satu dari mereka dengan suara keras, supaya ada yang merasa didukung ketika bertengkar dengan yang lain di rumah"],answer:1,explain:"Kamu tidak bisa memaksa orang lain menyimak, tetapi memberi contoh & membuat tiap orang merasa didengar bisa menurunkan panas.",hint:"Memberi contoh & mendengar tiap pihak, atau ikut memihak / menyalahkan?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti mendengarkan aktif:",options:["Tunggu giliran bicara sambil menyiapkan jawaban terbaikmu, lalu sampaikan dengan percaya diri tanpa perlu memahami dulu isi ucapan maupun perasaan lawan bicara","Selalu beri solusi secepat mungkin kepada siapa pun yang bercerita, tanpa perlu bertanya apa yang sebenarnya ia rasakan, butuhkan, atau inginkan saat itu","Beri perhatian penuh untuk memahami maksud & perasaan orang, tahan memotong & menghakimi, cek pemahaman dengan merangkum & bertanya, dan tunjukkan lewat tindak lanjut"],answer:2,explain:"Ringkasan: hadir penuh → pahami (fakta + perasaan) → tahan diri → konfirmasi → tindak lanjut. Menyimak adalah memahami, bukan menyetujui atau menyelesaikan.",hint:"Perhatian penuh, pahami, tahan diri, cek, tindak lanjut — rangkai."},
{n:98,type:"tf",micro:"Refleksi: menyimak & belajar",q:"Benar atau Salah: Orang yang paling banyak bicara dalam sebuah percakapan biasanya yang paling banyak belajar dari percakapan itu.",answer:false,explain:"Sebaliknya, kamu menyerap sudut pandang & informasi baru justru saat menyimak, bukan saat bicara. Pendengar yang baik cenderung belajar lebih banyak.",hint:"Lebih banyak menyerap saat bicara, atau saat menyimak?"},
{n:99,type:"mcq",micro:"Kasus: menyimak diri di akhir hari",q:"Cara melatih menyimak lewat refleksi harian:",options:["Setiap malam, ingat satu percakapan: apakah aku memotong? apakah aku ingat perasaan lawan bicara? apa yang bisa kuperbaiki besok?","Tidak pernah mengevaluasi diri sama sekali, karena merasa kemampuan menyimakmu sudah cukup baik sejak dahulu & tidak perlu dilatih","Menyalahkan orang lain yang diajak bicara karena mereka membosankan, sehingga kamu sulit memperhatikan & tidak perlu mengubah apa pun"],answer:0,explain:"Refleksi singkat & jujur mengubah pengalaman sehari-hari menjadi latihan yang terarah.",hint:"Evaluasi jujur harian, atau menyalahkan orang lain?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi menyimak",q:"Tulis 'aturan pribadi mendengarkan' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: singkirkan gangguan/perhatian penuh, jangan memotong, tanya kebutuhan sebelum menasihati, rangkum/konfirmasi, jaga kerahasiaan (dengan pengecualian bahaya), tindak lanjut, jaga batas diri.",hint:"Ambil satu pelajaran dari tiap fase — perhatian penuh, tahan memotong, tanya kebutuhan, merangkum, jaga rahasia, tindak lanjut — dan ubah jadi aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Saat seseorang bercerita, aku menyingkirkan HP dan menghadap ke mereka — karena perhatian penuh adalah tanda menghargai. (2) Aku menunggu orang benar-benar selesai sebelum menanggapi — karena memotong membuat mereka kehilangan alur dan merasa tak dihargai. (3) Sebelum memberi pendapat atau solusi, aku bertanya 'kamu mau didengar saja atau mau masukan?' — karena tidak semua orang yang curhat mencari nasihat. (4) Aku merangkum ulang inti dan perasaan yang kutangkap ('jadi kamu kesal karena...') — karena ini mencegah salah paham dan menunjukkan aku menyimak. (5) Aku tidak menyebarkan cerita pribadi yang dibagikan kepadaku, kecuali ada bahaya serius yang butuh orang dewasa — karena kepercayaan runtuh kalau rahasia bocor. (6) Aku menindaklanjuti: menanyakan kabar cerita itu di kemudian hari — karena itu bukti aku benar-benar mendengar. (7) Aku menjaga batas: bila percakapan berubah menyakiti, aku boleh mengakhirinya dengan sopan."},
];
